         if config!(self.config, document).indentation == Indentation::Tabs {
             self.character('\t')?;
         } else {
             let tab_width = config!(self.config, document).tab_width;
             for _ in 0..tab_width {
                 self.character(' ')?;
             }
         }
         Ok(())
     }
