+/// Edit prediction engine — sends code context to a local LLM (Zeta 2.1)
+/// and displays inline ghost text predictions.
+///
+/// ## Prompt format (Zeta 2.1 multi-region)
+///
+/// ```text
+/// <[fim-suffix]>
+/// code after cursor
+/// <[fim-prefix]><filename>path/to/file
+/// code before cursor
+/// <|marker_1|>
+/// current line content<|user_cursor|>
+/// <|marker_2|>
+/// <[fim-middle]>
+/// ```
+///
+/// The model streams/predicts the new content between `<|marker_1|>` and `<|marker_2|>`.
+use crate::config::prediction::Prediction;
+use std::sync::mpsc::{self, Receiver, Sender};
+use std::sync::{Arc, Mutex};
+use std::thread;
+use std::time::{Duration, Instant};
