+/// An active prediction shown to the user
+#[derive(Debug, Clone)]
+pub struct ActivePrediction {
+    /// The text the model predicted (what replaces the region between markers)
+    pub text: String,
+    /// The line (0-based) where this prediction applies
+    pub cursor_y: usize,
+    /// The character offset (x) where the cursor was when this was triggered
+    pub cursor_x: usize,
+}
+
+/// Events emitted by the prediction engine back to the editor
+#[derive(Debug)]
+pub enum PredictionEvent {
+    /// A new prediction is ready
+    Ready(ActivePrediction),
+    /// An error occurred (logged, not shown to user)
+    Error(String),
+}
+
+// ---------------------------------------------------------------------------
+// Internal command types
+// ---------------------------------------------------------------------------
