+/// Manages the prediction lifecycle — debounce, HTTP request, rendering state.
+pub struct PredictionEngine {
+    /// Shared configuration (mutable from Lua)
+    config: Arc<Mutex<Prediction>>,
+    /// Channel to send trigger/shutdown commands to the worker thread
+    cmd_tx: Sender<Command>,
+    /// Channel to receive prediction results from the worker thread
+    evt_rx: Receiver<PredictionEvent>,
+    /// The currently displayed prediction (if any)
+    current_prediction: Option<ActivePrediction>,
+    /// When the last key was pressed (for debounce)
+    last_key_time: Instant,
+    /// Whether we've already sent a trigger (don't re-send until response)
+    pending: bool,
+}
+
