+        // Grab context lines around the cursor
+        let ctx_before_start = cursor_y.saturating_sub(max_ctx / 2);
+        let ctx_after_end = std::cmp::min(total, cursor_y + max_ctx / 2);
+
+        let lines_before: Vec<String> = all_lines[ctx_before_start..cursor_y]
+            .iter()
+            .map(ToString::to_string)
+            .collect();
+        let cursor_line = all_lines
+            .get(cursor_y)
+            .cloned()
+            .unwrap_or_default();
+        let lines_after: Vec<String> = all_lines[(cursor_y + 1)..ctx_after_end]
+            .iter()
+            .map(ToString::to_string)
+            .collect();
+
+        self.pending = true;
+
+        let _ = self.cmd_tx.send(Command::Trigger {
+            cursor_y,
+            cursor_x,
+            lines_before,
+            cursor_line,
+            lines_after,
+            filename,
+        });
+    }
+
+    /// Check for new predictions from the worker (non-blocking).
+    /// Should be called before each render.
+    pub fn poll(&mut self) {
+        while let Ok(evt) = self.evt_rx.try_recv() {
+            self.pending = false;
+            match evt {
+                PredictionEvent::Ready(pred) => {
+                    self.current_prediction = Some(pred);
+                }
+                PredictionEvent::Error(_err) => {
+                    // Silently drop errors — they're logged in the worker
+                    self.current_prediction = None;
+                }
+            }
+        }
+    }
+
+    /// Whether a prediction is currently active and visible.
+    pub fn has_prediction(&self) -> bool {
+        self.current_prediction.is_some()
+    }
+
+    /// If there is an active prediction, return a reference to it.
+    pub fn current_prediction(&self) -> Option<&ActivePrediction> {
+        self.current_prediction.as_ref()
+    }
+
+    /// Accept the current prediction — returns the predicted text.
+    /// The caller must insert it into the document.
+    pub fn accept(&mut self) -> Option<ActivePrediction> {
+        self.pending = false;
+        self.current_prediction.take()
+    }
+
+    /// Dismiss the current prediction without accepting.
+    pub fn dismiss(&mut self) {
+        self.pending = false;
+        self.current_prediction = None;
+    }
+
+    /// Clear prediction state (e.g. on cursor movement).
+    pub fn clear(&mut self) {
+        self.pending = false;
+        self.current_prediction = None;
+    }
+
+    /// Check if enough time has elapsed since the last keystroke.
+    /// The caller should call this to decide whether to trigger a prediction.
+    pub fn debounce_elapsed(&self) -> bool {
+        let ms = self.config.lock().unwrap().debounce_ms;
+        self.last_key_time.elapsed() >= Duration::from_millis(ms)
+    }
+
+    /// Check the debounce and trigger prediction if appropriate.
+    /// Returns true if a request was sent.
+    pub fn check_and_trigger(
+        &mut self,
+        cursor_y: usize,
+        cursor_x: usize,
+        all_lines: &[String],
+        filename: Option<String>,
+    ) -> bool {
+        if !self.config.lock().unwrap().enabled {
+            return false;
+        }
+        if self.pending {
+            return false;
+        }
+        if self.debounce_elapsed() {
+            self.on_keystroke(cursor_y, cursor_x, all_lines, filename);
+            return true;
+        }
+        false
+    }
+}
+
+// ---------------------------------------------------------------------------
+// Worker thread
+// ---------------------------------------------------------------------------
+
+#[allow(clippy::too_many_lines, clippy::needless_pass_by_value)]
+fn worker_loop(
+    cmd_rx: Receiver<Command>,
+    evt_tx: Sender<PredictionEvent>,
+    config: Arc<Mutex<Prediction>>,
+) {
+    while let Ok(Command::Trigger {
+        cursor_y,
+        cursor_x,
+        lines_before,
+        cursor_line,
+        lines_after,
+        filename,
+    }) = cmd_rx.recv()
+    {
+        let cfg = config.lock().unwrap();
+        if !cfg.enabled {
+            continue;
+        }
+        let server_url = cfg.server_url.clone();
+        let model = cfg.model.clone();
+        let api_type = cfg.api_type.clone();
+        let max_tokens = cfg.max_tokens;
+        let temperature = cfg.temperature;
+        drop(cfg);
+
+        // Build the Zeta 2.1 multi-region prompt
+        let prompt = build_zeta_prompt(
+            &lines_before,
+            &cursor_line,
+            cursor_x,
+            &lines_after,
+            filename.as_deref(),
+        );
+
+        // Send to LLM
+        match send_prediction_request(&server_url, &model, &api_type, &prompt, max_tokens, temperature) {
+            Ok(prediction_text) => {
+                // Parse the model output: extract content between markers
+                let text = extract_between_markers(&prediction_text);
+                if !text.is_empty() {
+                    let evt = PredictionEvent::Ready(ActivePrediction {
+                        text,
+                        cursor_y,
+                        cursor_x,
+                    });
+                    let _ = evt_tx.send(evt);
+                }
+            }
+            Err(err) => {
+                let _ = evt_tx.send(PredictionEvent::Error(err));
+            }
+        }
+    }
+}
+
+// ---------------------------------------------------------------------------
+// Zeta 2.1 prompt construction
+// ---------------------------------------------------------------------------
+
+/// Build the multi-region SPM prompt that Zeta 2.1 expects.
+///
+/// Format:
+/// ```text
+/// <[fim-suffix]>
+/// code after editable region
+/// <[fim-prefix]><filename>path/to/file
+/// code before editable region
+/// <|marker_1|>
+/// current content<|user_cursor|>
+/// <|marker_2|>
+/// <[fim-middle]>
+/// ```
+fn build_zeta_prompt(
+    lines_before: &[String],
+    cursor_line: &str,
+    cursor_x: usize,
+    lines_after: &[String],
+    filename: Option<&str>,
+) -> String {
+    // The "code after editable region" — lines after the cursor
+    let after = lines_after.join("\n");
+
+    // The "code before editable region" — lines before the cursor
+    let before = lines_before.join("\n");
+
+    // The line content split at cursor: left side (before cursor) goes in prefix,
+    // right side (after cursor) is wrapped between markers
+    let (prefix_before, suffix_after) = split_at_char(cursor_line, cursor_x);
+
+    let file_tag = filename
+        .map(|f| format!("<filename>{f}"))
+        .unwrap_or_default();
+
+    format!(
+        "<[fim-suffix]>\n\
+         {after}\n\
+         <[fim-prefix]>{file_tag}\n\
+         {before}\n\
+         <|marker_1|>\n\
+         {prefix_before}<|user_cursor|>\n\
+         {suffix_after}\n\
+         <|marker_2|>\n\
+         <[fim-middle]>"
+    )
+}
+
+/// Split a string at a byte/char index (char boundary safe).
+/// Returns (before, after).
+fn split_at_char(s: &str, char_idx: usize) -> (&str, &str) {
+    for (count, (i, _)) in s.char_indices().enumerate() {
+        if count == char_idx {
+            return (&s[..i], &s[i..]);
+        }
+    }
+    // char_idx >= char count → after is empty
+    (s, "")
+}
+
+/// Extract text between the first `<|marker_1|>` and `<|marker_2|>` markers
+/// in the model's response.
+fn extract_between_markers(response: &str) -> String {
+    // Try to find marker_1 and marker_2
+    if let Some(m1_start) = response.find("<|marker_1|>") {
+        let content_start = m1_start + "<|marker_1|>".len();
+        let rest = &response[content_start..];
+        if let Some(m2_end) = rest.find("<|marker_2|>") {
+            let content = &rest[..m2_end];
+            // Strip leading/trailing whitespace but keep internal newlines
+            return content.trim().to_string();
+        }
+        // No marker_2 found, use everything after marker_1
+        return rest.trim().to_string();
+    }
+    // No markers — return the whole response trimmed (fallback)
+    response.trim().to_string()
+}
+
+// ---------------------------------------------------------------------------
+// HTTP request
+// ---------------------------------------------------------------------------
+
+/// Send an edit prediction request to the LLM server.
+/// Supports both Ollama and OpenAI-compatible APIs.
+fn send_prediction_request(
+    server_url: &str,
+    model: &str,
+    api_type: &str,
+    prompt: &str,
+    max_tokens: u32,
+    temperature: f64,
+) -> std::result::Result<String, String> {
+    let base = server_url.trim_end_matches('/');
+    let escaped_prompt = json_escape(prompt);
+
+    let (url, body) = match api_type {
+        "ollama" => (
+            format!("{base}/api/generate"),
+            format!(
+                r#"{{"model":"{}","prompt":"{}","options":{{"temperature":{},"max_tokens":{}}},"stream":false}}"#,
+                json_escape(model),
+                escaped_prompt,
+                temperature,
+                max_tokens,
+            ),
+        ),
+        // OpenAI-compatible (LM Studio, vLLM, llama.cpp server, etc.)
+        _ => (
+            format!("{base}/completions"),
+            format!(
+                r#"{{"model":"{}","prompt":"{}","max_tokens":{},"temperature":{},"stream":false}}"#,
+                json_escape(model),
+                escaped_prompt,
+                max_tokens,
+                temperature,
+            ),
+        ),
+    };
+
+    // Send request
+    let resp = ureq::post(&url)
+        .header("Content-Type", "application/json")
+        .send(body.clone())
+        .map_err(|e| format!("HTTP request failed: {e}"))?;
+
+    let resp_text = resp
+        .into_body()
+        .read_to_string()
+        .map_err(|e| format!("Failed to read response: {e}"))?;
+
+    // Parse JSON response for Ollama format: {"response": "..."} or
+    // OpenAI-compatible: {"choices": [{"text": "..."}]}
+    parse_response(&resp_text)
+}
+
+/// Very minimal JSON string escaper (handles quotes, backslashes, newlines).
+fn json_escape(s: &str) -> String {
+    let mut out = String::with_capacity(s.len() + 8);
+    for ch in s.chars() {
+        match ch {
+            '"' => out.push_str("\\\""),
+            '\\' => out.push_str("\\\\"),
+            '\n' => out.push_str("\\n"),
+            '\r' => out.push_str("\\r"),
+            '\t' => out.push_str("\\t"),
+            c => out.push(c),
+        }
+    }
+    out
+}
+
+/// Parse the model response JSON, supporting both Ollama and `OpenAI`-compatible formats.
+fn parse_response(resp_text: &str) -> std::result::Result<String, String> {
+    // Try Ollama format: {"response": "text"}
+    if let Some(response_pos) = resp_text.find(r#""response""#) {
+        let after_key = &resp_text[response_pos + r#""response""#.len()..];
+        if let Some(colon_pos) = after_key.find(':') {
+            let after_colon = after_key[colon_pos + 1..].trim();
+            if let Some(val_start) = after_colon.find('"') {
+                let val_start_abs = val_start + 1;
+                let remaining = &after_colon[val_start_abs..];
+                // Find the closing quote (not escaped)
+                if let Some(val_end) = find_unescaped_quote(remaining) {
+                    let unescaped = json_unescape(&remaining[..val_end]);
+                    return Ok(unescaped);
+                }
+            }
+        }
+    }
+
+    // Try OpenAI format: {"choices": [{"text": "..."}]}
+    if let Some(text_pos) = resp_text.find(r#""text""#) {
+        let after_key = &resp_text[text_pos + r#""text""#.len()..];
+        if let Some(colon_pos) = after_key.find(':') {
+            let after_colon = after_key[colon_pos + 1..].trim();
+            if let Some(val_start) = after_colon.find('"') {
+                let val_start_abs = val_start + 1;
+                let remaining = &after_colon[val_start_abs..];
+                if let Some(val_end) = find_unescaped_quote(remaining) {
+                    let unescaped = json_unescape(&remaining[..val_end]);
+                    return Ok(unescaped);
+                }
+            }
+        }
+    }
+
+    Err(format!("Could not parse model response: {resp_text}"))
+}
+
+/// Find the next  double-quote character.
+fn find_unescaped_quote(s: &str) -> Option<usize> {
+    let mut chars = s.char_indices();
+    while let Some((i, ch)) = chars.next() {
+        if ch == '\\' {
+            // Skip escaped character
+            chars.next();
+        } else if ch == '"' {
+            return Some(i);
+        }
+    }
+    None
+}
+
+/// Minimal JSON un-escaper for response text.
+fn json_unescape(s: &str) -> String {
+    let mut out = String::with_capacity(s.len());
+    let mut chars = s.chars();
+    while let Some(ch) = chars.next() {
+        if ch == '\\' {
+            match chars.next() {
+                Some('n') => out.push('\n'),
+                Some('r') => out.push('\r'),
+                Some('t') => out.push('\t'),
+                Some('"') => out.push('"'),
+                Some('\\') | None => out.push('\\'),
+                Some(c) => {
+                    out.push('\\');
+                    out.push(c);
+                }
+            }
+        } else {
+            out.push(ch);
+        }
+    }
+    out
+}

